body:
Sorry, I should have mentioned originally that this also happens without symlinks.  Here's a minimal repro:

```
# set up initial project

mkdir repro && cd repro
npm init -y
npm install eslint@2.4.0 babel-eslint@5.0.0 babel-preset-es2015-node5@1.1.2 estraverse-fb@1.3.1
echo '{ "parser": "babel-eslint", "env": {"node": true, "es6": true}, "ecmaFeatures": {"modules": true, "blockBindings": true, "destructuring": true}, "rules":{"prefer-const": 2} }' > .eslintrc
echo '{ "presets": ["es2015-node5"], ignore: ["node_modules", "commonjs"] }' > .babelrc
echo -e "export let foo = (array) => {\n  let [a, b] = array\n  console.log(a, "a", b, "b")\n}" > test.js

# eslint runs normally and catches prefer-const violations:
node node_modules/eslint/bin/eslint.js test.js

mkdir commonjs
mv node_modules/babel-eslint/ commonjs/

# this should run normally, but fails with
#   Cannot find module 'babel-eslint' from '/private/tmp/repro/node_modules'
NODE_PATH=node_modules:commonjs node node_modules/eslint/bin/eslint.js test.js


# create a patch file

cat > config.patch <<'EOF'
--- node_modules/eslint/lib/config/config-file.js 2016-03-07 21:15:46.000000000 +0000
+++ config-file-patched.js 2016-03-14 10:18:18.000000000 +0000
@@ -450,7 +450,7 @@

         // include full path of parser if present
         if (config.parser) {
-            config.parser = resolveModule.sync(config.parser, {basedir: basedir});
+            config.parser = resolveParser(config.parser, filePath);
         }

         // validate the configuration before continuing
@@ -472,6 +472,20 @@
     return config;
 }

+function resolveParser(parser, filePath) {
+  try {
+    return require.resolve(parser);
+  } catch (e) {
+    try {
+      return require.resolve('eslint-plugin-', parser);
+    } catch (e) {
+      return resolveModule.sync(parser, {
+          basedir: getLookupPath(path.dirname(path.resolve(filePath)))
+      });
+    }
+  }
+}
+
 //------------------------------------------------------------------------------
 // Public Interface
 //------------------------------------------------------------------------------
EOF


# apply the patch
patch -p0 < config.patch

# now eslint should run and catch prefer-const violations again
NODE_PATH=node_modules:commonjs node node_modules/eslint/bin/eslint.js test.js
```
